package com.secureauth;

import com.sun.net.httpserver.*;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.*;

public class Main {
 static final Path DATA=Paths.get("data"), USERS=DATA.resolve("users.tsv"), EVENTS=DATA.resolve("events.tsv");
 static final Map<String,String> users=new ConcurrentHashMap<>();
 static final List<Event> events=Collections.synchronizedList(new ArrayList<>());
 static final Map<String,Long> blocks=new ConcurrentHashMap<>();
 static final SecureRandom random=new SecureRandom();
 static final String ADMIN_TOKEN=UUID.randomUUID().toString();
 record Event(long time,String user,String ip,String result,String reason) {}
 static String hash(String password,String salt) throws Exception { byte[] key=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(new PBEKeySpec(password.toCharArray(),Base64.getDecoder().decode(salt),210000,256)).getEncoded();return Base64.getEncoder().encodeToString(key); }
 static String createHash(String pass) throws Exception {byte[] salt=new byte[16];random.nextBytes(salt);String s=Base64.getEncoder().encodeToString(salt);return s+":"+hash(pass,s);}
 static boolean check(String pass,String stored) {try {String[] p=stored.split(":",2);return MessageDigest.isEqual(hash(pass,p[0]).getBytes(StandardCharsets.UTF_8),p[1].getBytes(StandardCharsets.UTF_8));}catch(Exception e){return false;}}
 static void load() throws Exception {Files.createDirectories(DATA);if(Files.exists(USERS))for(String line:Files.readAllLines(USERS)){String[] a=line.split("\t",2);if(a.length==2)users.put(a[0],a[1]);}if(Files.exists(EVENTS))for(String line:Files.readAllLines(EVENTS)){String[] a=line.split("\t",5);if(a.length==5)try{events.add(new Event(Long.parseLong(a[0]),a[1],a[2],a[3],a[4]));}catch(NumberFormatException ignored){}}}
 static synchronized void saveUser(String user,String pass) throws Exception {String value=createHash(pass);users.put(user,value);Files.writeString(USERS,user+"\t"+value+"\n",StandardOpenOption.CREATE,StandardOpenOption.APPEND);}
 static synchronized void log(String user,String ip,String result,String reason) throws IOException {Event e=new Event(System.currentTimeMillis(),user,ip,result,reason);events.add(e);Files.writeString(EVENTS,e.time+"\t"+e.user+"\t"+e.ip+"\t"+e.result+"\t"+e.reason+"\n",StandardOpenOption.CREATE,StandardOpenOption.APPEND);}
 static Map<String,String> form(HttpExchange x)throws IOException {String body=new String(x.getRequestBody().readNBytes(8192),StandardCharsets.UTF_8);Map<String,String> m=new HashMap<>();for(String part:body.split("&")){String[] a=part.split("=",2);if(a.length==2)m.put(URLDecoder.decode(a[0],StandardCharsets.UTF_8),URLDecoder.decode(a[1],StandardCharsets.UTF_8));}return m;}
 static String esc(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
 static void send(HttpExchange x,int status,String html)throws IOException {byte[] b=html.getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","text/html; charset=utf-8");x.getResponseHeaders().set("Cache-Control","no-store");x.getResponseHeaders().set("X-Content-Type-Options","nosniff");x.getResponseHeaders().set("Content-Security-Policy","default-src 'none'; style-src 'unsafe-inline'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'");x.sendResponseHeaders(status,b.length);try(OutputStream o=x.getResponseBody()){o.write(b);}}
 static String page(String title,String body){return "<!doctype html><html lang='en'><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>"+esc(title)+" | SecureAuth Guard</title><style>body{font:16px system-ui;background:#0b1220;color:#e7eefb;margin:0}main{max-width:1060px;margin:45px auto;padding:20px}h1{font-size:32px}p{color:#aebed4}.card{background:#172338;border:1px solid #30405b;border-radius:14px;padding:25px;margin:16px 0}input,button{padding:12px;border-radius:8px;border:1px solid #546783;margin:7px 5px 7px 0}button{background:#3b82f6;color:white;cursor:pointer}input{background:#0b1220;color:white}a{color:#93c5fd}table{width:100%;border-collapse:collapse;font-size:14px}td,th{padding:11px;border-bottom:1px solid #30405b;text-align:left}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.metric{font-size:30px;font-weight:bold;color:#93c5fd}.alert{color:#fda4af}</style><main><h1>🛡️ SecureAuth Guard</h1><p>Java-based login brute-force detection and security monitoring</p>"+body+"</main></html>";}
 static String clientIp(HttpExchange x){return x.getRemoteAddress().getAddress().getHostAddress();} // Ignore spoofable X-Forwarded-For
 static long count(String user,String ip,long since,String mode){synchronized(events){return events.stream().filter(e->e.time>=since&&e.result.equals("FAIL")&&(mode.equals("user")?e.user.equals(user):e.ip.equals(ip))).count();}}
 static long distinctUsers(String ip,long since){synchronized(events){return events.stream().filter(e->e.time>=since&&e.result.equals("FAIL")&&e.ip.equals(ip)).map(Event::user).distinct().count();}}
 static String login(String user,String pass,String ip)throws Exception {long now=System.currentTimeMillis(),since=now-300000;blocks.entrySet().removeIf(e->e.getValue()<now);if(blocks.getOrDefault(ip,0L)>now){log(user,ip,"BLOCK","IP rate limit");return "Request temporarily restricted. Try again later.";}
 boolean valid=users.containsKey(user)&&check(pass,users.get(user));if(valid){log(user,ip,"SUCCESS","Valid credentials");return "Login successful for "+esc(user)+".";}
 log(user,ip,"FAIL","Invalid credentials");long ipFails=count(user,ip,since,"ip"),accountFails=count(user,ip,since,"user"),targets=distinctUsers(ip,since);
 if(ipFails>=10||targets>=4){blocks.put(ip,now+120000);log(user,ip,"ALERT",targets>=4?"Possible password spraying":"Possible brute force from IP");return "Suspicious activity detected. Source temporarily restricted for 2 minutes.";}
 if(accountFails>=5){log(user,ip,"ALERT","Multiple failed logins for account");return "Invalid credentials. Security monitoring is active.";}
 return "Invalid username or password.";}
 static String dashboard(){List<Event> snapshot; synchronized(events){snapshot=new ArrayList<>(events);}long failures=snapshot.stream().filter(e->e.result.equals("FAIL")).count(),success=snapshot.stream().filter(e->e.result.equals("SUCCESS")).count(),alerts=snapshot.stream().filter(e->e.result.equals("ALERT")).count();StringBuilder b=new StringBuilder("<div class='grid'>");for(String[] m:new String[][]{{"Successful logins",""+success},{"Failed logins",""+failures},{"Security alerts",""+alerts},{"Restricted IPs",""+blocks.size()}})b.append("<div class='card'>").append(esc(m[0])).append("<div class='metric'>").append(m[1]).append("</div></div>");b.append("</div><div class='card'><h2>Recent security events</h2><table><tr><th>Time</th><th>Account</th><th>Source IP</th><th>Event</th><th>Details</th></tr>");Collections.reverse(snapshot);for(Event e:snapshot.stream().limit(100).toList())b.append("<tr><td>").append(esc(Instant.ofEpochMilli(e.time).toString())).append("</td><td>").append(esc(e.user)).append("</td><td>").append(esc(e.ip)).append("</td><td>").append(esc(e.result)).append("</td><td>").append(esc(e.reason)).append("</td></tr>");return b.append("</table></div><p>Dashboard is protected by a random admin token printed on server startup. Demo only; use proper admin authentication for deployment.</p>").toString();}
 public static void main(String[] args)throws Exception {load();if(users.isEmpty()){String pass=UUID.randomUUID().toString().substring(0,12);saveUser("student",pass);System.out.println("Demo student username: student | password: "+pass);}HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",8080),0);server.setExecutor(Executors.newFixedThreadPool(12));server.createContext("/",x->{try{String path=x.getRequestURI().getPath();if(path.equals("/dashboard")){String token=Optional.ofNullable(x.getRequestURI().getRawQuery()).orElse("").replaceFirst("^token=","");if(!MessageDigest.isEqual(token.getBytes(StandardCharsets.UTF_8),ADMIN_TOKEN.getBytes(StandardCharsets.UTF_8))){send(x,403,page("Forbidden","<div class='card'>Administrator token required.</div>"));return;}send(x,200,page("Dashboard",dashboard()));return;}if(path.equals("/login")&&x.getRequestMethod().equals("POST")){Map<String,String> f=form(x);String user=f.getOrDefault("username","").trim(),pass=f.getOrDefault("password","");if(user.length()>64||pass.length()>256||user.contains("\t")||user.contains("\n")){send(x,400,page("Error","Invalid input."));return;}String message=login(user,pass,clientIp(x));send(x,200,page("Login result","<div class='card'><h2>"+message+"</h2><a href='/'>Back to login</a></div>"));return;}if(path.equals("/")&&x.getRequestMethod().equals("GET")){send(x,200,page("Login","<div class='card'><h2>Student Portal Login</h2><form method='POST' action='/login'><label>Username<br><input name='username' maxlength='64' required autocomplete='username'></label><br><label>Password<br><input type='password' name='password' maxlength='256' required autocomplete='current-password'></label><br><button>Sign in</button></form></div><p>Security features: PBKDF2 password hashing, event audit log, 5-minute detection window, IP restrictions, account alerts and password spraying detection.</p>"));return;}send(x,404,page("Not found","Page not found."));}catch(Exception e){e.printStackTrace();send(x,500,page("Error","Unexpected server error."));}});server.start();System.out.println("Login: http://127.0.0.1:8080/");System.out.println("Admin dashboard: http://127.0.0.1:8080/dashboard?token="+ADMIN_TOKEN);}
}
